'use strict';
const S={authenticated:false,setup:false,me:null,config:null,messages:[],stats:null,bayesStats:null,fuzzyStats:null,fuzzyEntries:[],neuralStats:null,signals:[],runtime:null,hostReport:null,section:'overview',inspect:null,search:'',filterAction:'all',onceToken:null,menu:false,deliveryQueue:null,historyResults:null,historyOffset:0,editRule:null,preview:null,diagnostics:null};
const $=q=>document.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const n=v=>Number(v||0).toLocaleString();
const fmtDate=v=>v?new Date(v).toLocaleString(undefined,{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}):'—';
const action=v=>`<span class="action-label ${esc(v)}">${esc(v||'unknown')}</span>`;
function alertUser(msg,bad=false){let prev=$('.toast');if(prev)prev.remove();const el=document.createElement('div');el.className='toast'+(bad?' fail':'');el.textContent=msg;el.setAttribute('role','status');document.body.appendChild(el);setTimeout(()=>el.remove(),5500)}
async function api(path,options={}){
  const headers={...(options.headers||{})};if(S.me?.csrf&&options.method&&options.method!=='GET')headers['X-CSRF-Token']=S.me.csrf;
  if(options.json!==undefined){headers['Content-Type']='application/json';options.body=JSON.stringify(options.json)}
  const response=await fetch(path,{credentials:'same-origin',cache:'no-store',...options,headers});let data;
  try{data=await response.json()}catch{data={error:'Unexpected response from SpamGate'}}
  if(!response.ok)throw Error(data?.error||`Request failed (${response.status})`);return data;
}
async function start(){try{const status=await api('/api/v1/status');if(!status.configured){S.setup=true;render();return}try{S.me=await api('/api/v1/me');S.authenticated=true;S.section=permitted(sectionFromLocation())?sectionFromLocation():'overview';await refresh()}catch{S.authenticated=false;render()}}catch(e){$('#app').innerHTML=`<div class="auth-side"><div class="auth-panel"><h1>Cannot connect</h1><p>${esc(e.message)}</p><button class="primary" id="retry">Retry connection</button></div></div>`}}
async function refresh(){if(!S.authenticated)return;try{const [cfg,msg,stats,signals,bayes,fuzzy,entries,neural]=await Promise.all([api('/api/v1/config'),api('/api/v1/messages?limit=1000'),api('/api/v1/statistics'),api('/api/v1/signals'),S.me.role==='admin'?api('/api/v1/bayes/stats'):Promise.resolve(null),S.me.role==='admin'?api('/api/v1/fuzzy/stats'):Promise.resolve(null),S.me.role==='admin'?api('/api/v1/fuzzy/entries'):Promise.resolve([]),S.me.role==='admin'?api('/api/v1/neural/stats'):Promise.resolve(null)]);S.config=cfg;S.messages=Array.isArray(msg)?msg:[];S.stats=stats;S.signals=Array.isArray(signals)?signals:[];S.bayesStats=bayes;S.fuzzyStats=fuzzy;S.fuzzyEntries=entries;S.neuralStats=neural;
    if(S.me.role==='admin') {
      try{S.runtime=await api('/api/v1/runtime')}catch{S.runtime=null}
      try{S.hostReport=await api('/api/v1/host')}catch{S.hostReport=null}
      try{S.deliveryQueue=await api('/api/v1/delivery-queue')}catch{S.deliveryQueue=null}
    } else S.runtime=null;
    render()}catch(e){alertUser(e.message,true);if(e.message.includes('Authentication')){S.authenticated=false;render()}}}
const navigation=[
 ['overview','Command center','/overview','Operations'],
 ['investigate','Investigations','/investigations','Operations'],
 ['quarantine','Quarantine','/quarantine','Operations'],
 ['history','Mail activity','/messages','Operations'],
 ['threats','Threat intelligence','/threat-intelligence','Protection'],
 ['rules','Policy rules','/rules','Protection'],
 ['signals','Detection signals','/signals','Protection'],
 ['lists','DNS reputation','/blocklists','Protection'],
 ['learning','Machine learning','/learning','Protection'],
 ['settings','Thresholds & retention','/policy','Configuration'],
 ['connect','Mail integrations','/connections','Configuration'],
 ['delivery','Delivery queue','/delivery-queue','Configuration'],
 ['users','Mailbox access','/mailboxes','Configuration'],
 ['tokens','API credentials','/api-keys','Configuration'],
 ['scanlab','Scan workbench','/scan-workbench','Configuration'],
 ['docs','Help & reference','/help','Configuration']
];
const primarySections=new Set(['overview','investigate','quarantine','history','threats','connect']);
function permitted(id){return S.me?.role==='admin'||!['users','tokens','lists','settings','connect','learning','threats','delivery'].includes(id)}
function sectionFromLocation(){return navigation.find(r=>r[2]===window.location.pathname)?.[0]||'overview'}
function routeTo(id,replace=false){if(!navigation.some(r=>r[0]===id)||!permitted(id))return;S.section=id;S.inspect=null;const path=navigation.find(r=>r[0]===id)[2];if(window.location.pathname!==path)window.history[replace?'replaceState':'pushState']({section:id},'',path);render();window.scrollTo(0,0)}

function authLayout(){const first=S.setup;return `<div class="auth-layout"><aside class="auth-brand"><a class="brand-lockup" href="/overview"><span class="brand-emblem" aria-hidden="true">SG</span><span class="brand-word">SpamGate<small>MAIL SECURITY / LOCAL CONTROL</small></span></a><div><div class="hero-rule" style="color:#E7BE58">MADE FOR THE MAIL THAT MATTERS</div><h1>Know exactly why.</h1><p>A clear record of what arrived, what matched, how it scored, and who changed the decision.</p></div><div><div class="auth-graphic" aria-hidden="true"><div class="line"></div><div class="line"></div><div class="line"></div><div class="line"></div></div><small>NO HIDDEN SCORING · NO DEFAULT ADMIN PASSWORD</small></div></aside><main id="main" class="auth-side"><section class="auth-panel"><div class="overline">${first?'NEW INSTALLATION / 01':'SECURE LOGIN / SPAMGATE'}</div><h1>${first?'Make it yours.':'Back at the desk.'}</h1><p>${first?'Set the installation name and create the first administrator. On Windows the first-run key is displayed in a native dialog.':'Sign in to investigate mail, tune scoring, and manage mail security.'}</p><form id="${first?'setup-form':'login-form'}">${first?`<div class="field"><label for="setupkey">First-run claim key</label><input id="setupkey" name="setup_key" required autocomplete="off" placeholder="Paste the claim key from SpamGate" spellcheck="false"></div><div class="field"><label for="sitename">Installation name</label><input id="sitename" name="site_name" value="SpamGate" required minlength="2" maxlength="80"></div>`:''}<div class="field"><label for="username">Administrator username</label><input id="username" name="username" required minlength="3" maxlength="48" autocomplete="username"></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="${first?'new-password':'current-password'}" required ${first?'minlength="12"':''}></div><button type="submit" class="primary">${first?'Create administrator':'Sign in'} ↗</button></form><div class="auth-foot">${first?'The claim key is unique to the current startup. Choose a password of at least 12 characters.':'Sessions expire after 12 hours. Repeated failed sign-in attempts are rate-limited.'}</div></section></main></div>`}

function layout(body){
 const selected=navigation.find(x=>x[0]===S.section)||navigation[0];
 const links=(area)=>navigation.filter(x=>x[3]===area&&permitted(x[0])&&!primarySections.has(x[0])).map(([id,label,path])=>`<a class="worknav-link ${id===S.section?'selected':''}" href="${path}" data-route="${id}" ${id===S.section?'aria-current="page"':''}>${esc(label)}${id===S.section?'<span aria-hidden="true">▰</span>':''}</a>`).join('');
 const queue=S.messages.filter(m=>m.delivery==='quarantined').length;
 const transports=S.runtime?.services||{};
 const active=['milter','smtp','rspamd_http'].filter(id=>transports[id]?.enabled).length;
 return `<header class="command-masthead">
   <div class="masthead-top">
     <a href="/overview" data-route="overview" class="logo-lockup" aria-label="SpamGate command center"><span class="logo-mark" aria-hidden="true"><svg width="35" height="35" viewBox="0 0 35 35"><path d="M3 8h29v20H3z M3 8l14.5 13L32 8" fill="none" stroke="currentColor" stroke-width="2.5"/></svg></span><span><strong>SpamGate</strong><small>MAIL DEFENSE CONTROL</small></span></a>
     <div class="masthead-status"><div class="masthead-monitor"><span class="monitor-dot"></span><span><b>Management online</b><small>${S.me.role==='admin'?(active?`${active} mail filtering listener${active===1?'':'s'} configured`:'No mail filtering listener configured'):'Mailbox view'}</small></span></div><span class="site-divider"></span><span class="masthead-site">${esc(S.config?.settings?.site_name||'SpamGate')}</span><span class="whoami">${esc(S.me?.name||'')} · ${esc(S.me?.role||'')}</span><button class="logout" id="signout">Sign out</button></div>
   </div>
   <nav class="command-nav" aria-label="Primary mail operations">${navigation.filter(x=>primarySections.has(x[0])&&permitted(x[0])).map(([id,label,path])=>`<a data-route="${id}" href="${path}" class="command-link ${id===S.section?'selected':''}" ${id===S.section?'aria-current="page"':''}>${id==='quarantine'&&queue>0?`<b class="count-marker">${n(queue)}</b>`:''}${esc(label)}</a>`).join('')}</nav>
 </header>
 <div class="work-area">
   <div class="work-switch"><div><span class="work-switch-caption">WORKSPACE</span><span class="work-switch-path">${esc(selected[3])} <span aria-hidden="true">/</span> ${esc(selected[1])}</span></div><div class="work-switch-actions"><button class="refresh-link" id="reload" type="button">↻ Refresh data</button><time>${esc(new Date().toLocaleString())}</time></div></div>
   <div class="worknav" role="navigation" aria-label="Additional management workspaces"><div><span>Protection</span>${links('Protection')}</div><div><span>Configuration</span>${links('Configuration')}</div></div>
   <main id="main" tabindex="-1" class="defense-main">${body}<footer class="defense-footer"><span>SpamGate ${esc(S.stats?.version||'')} · Local control plane</span><span>History and verdicts are scoped to this installation · No simulated mail data</span></footer></main>
 </div>${S.inspect?detailView(S.inspect):''}`;
}

function heading(title,description,extra=''){
 return `<div class="screen-title"><div><div class="screen-context">${esc((navigation.find(x=>x[0]===S.section)||[])[3]||'Operations')} / ${esc((navigation.find(x=>x[0]===S.section)||[])[1]||'Mail defense')}</div><h1>${title}</h1><p>${description}</p></div>${extra?`<div class="screen-action">${extra}</div>`:''}</div>`;
}

function empty(title,description){return `<div class="empty"><b>${title}</b><p>${description}</p></div>`}
function table(rows){if(!rows.length)return empty('Nothing in the ledger yet.','Scan an .eml file or connect a mail server. Each verdict and its scoring evidence will appear here.');return `<div class="table-shell" role="region" aria-label="Message verdicts" tabindex="0"><table><thead><tr><th scope="col">Received</th><th scope="col">Message</th><th scope="col">Recipient</th><th scope="col">Score</th><th scope="col">Verdict</th><th scope="col">Evidence</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${esc(fmtDate(m.timestamp))}</td><td><div class="subject" title="${esc(m.subject||'(no subject)')}">${esc(m.subject||'(no subject)')}</div><small>${esc(m.sender||'Unknown sender')}</small></td><td>${esc((m.recipients||[]).join(', ')||'—')}</td><td class="score ${(m.score||0)>0?'pos':'neg'}">${Number(m.score||0)>0?'+':''}${Number(m.score||0).toFixed(2)}</td><td>${action(m.action)}</td><td><button class="table-link" data-inspect="${esc(m.id)}" aria-label="Inspect message ${esc(m.subject||m.id)}">Inspect ↗</button></td></tr>`).join('')}</tbody></table></div>`}


function getQueue(){return S.messages.filter(m=>m.delivery==='quarantined')}
function topFindings(limit=7){
 const result=new Map();
 for(const m of S.messages)for(const f of m.findings||[]){
  if(!f.symbol)continue;
  const r=result.get(f.symbol)||{symbol:f.symbol,source:f.source,count:0,score:0};
  r.count++;r.score+=Number(f.score)||0;result.set(f.symbol,r);
 }
 return [...result.values()].sort((a,b)=>b.count-a.count||b.score-a.score).slice(0,limit);
}
function topSenders(limit=6){
 const result=new Map();
 for(const m of S.messages){
  const domain=String(m.sender||'').split('@').pop().toLowerCase();
  if(!domain||!domain.includes('.'))continue;
  const row=result.get(domain)||{domain,count:0,flagged:0};
  row.count++;if(['tag','quarantine','reject'].includes(m.action))row.flagged++;
  result.set(domain,row);
 }
 return [...result.values()].sort((a,b)=>b.flagged-a.flagged||b.count-a.count).slice(0,limit);
}
function counts(){const a={accept:0,tag:0,quarantine:0,reject:0};for(const m of S.messages)if(Object.hasOwn(a,m.action))a[m.action]++;return a}
function previewRows(rows,limit=8){return `<div class="incident-list" role="list">${rows.slice(0,limit).map(m=>`<div class="incident" role="listitem"><div class="incident-mark ${esc(m.action)}"></div><div class="incident-content"><strong>${esc(m.subject||'(No subject)')}</strong><span>${esc(m.sender||'Unknown sender')} <span aria-hidden="true">·</span> ${esc((m.recipients||[]).join(', ')||'—')}</span></div><div class="incident-evidence"><span class="incident-score ${m.score>=0?'hot':''}">${m.score>=0?'+':''}${Number(m.score||0).toFixed(1)}</span><span>${n(m.findings?.length||0)} signals</span></div><div class="incident-result">${action(m.action)}<small>${esc(fmtDate(m.timestamp))}</small></div><button class="inspect-btn" data-inspect="${esc(m.id)}">Investigate <span aria-hidden="true">→</span></button></div>`).join('')||empty('No message records yet','Connect an MTA or use the scan workbench. All real decisions will appear here.')}</div>`}
function configurationStatus(){
 const services=S.runtime?.services||{};
 const enabled=['smtp','milter','rspamd_http'].filter(x=>services[x]?.enabled);
 const unknown=!S.runtime;
 const configured=enabled.length>0;
 return `<div class="integrity-strip ${configured?'configured':'attention'}"><span class="strip-symbol" aria-hidden="true">${configured?'◇':unknown?'?':'!'}</span><div><strong>${configured?'Filtering listener configured':unknown?'Listener status unavailable':'Mail protection is not yet configured'}</strong><p>${configured?`The application has ${enabled.length} MTA-facing listener${enabled.length===1?'':'s'} configured. This does not confirm external mail delivery or healthy upstream routing.`:unknown?(S.me?.role==='admin'?'SpamGate could not verify the currently configured listeners. Check application logs and API permissions.':'Detailed listener status is visible to administrators. Contact your mail system administrator to verify filtering.'):'The Web UI is responding. That alone does not mean any real email is protected. Configure a trusted Milter, SMTP, or Rspamd HTTP integration.'}</p></div><a href="/connections" data-route="connect">Review integrations →</a></div>`;
}
function verdictBars(){
 const c=counts(); const total=Object.values(c).reduce((a,b)=>a+b,0);
 const labels=[['accept','Accepted'],['tag','Tagged'],['quarantine','Quarantined'],['reject','Rejected']];
 return `<div class="verdict-bars">${labels.map(([id,label])=>`<div class="verdict-line"><div><span>${label}</span><strong>${n(c[id])}</strong></div><div class="verdict-track"><span class="bar-${id}" style="width:${total?(c[id]/total*100).toFixed(2):0}%"></span></div></div>`).join('')}</div>`;
}
function signalTable(){const top=topFindings();return top.length?`<div class="signals-ranked">${top.map((f,i)=>`<div class="ranked-row"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><div><b>${esc(f.symbol)}</b><small>${esc(f.source||'Scoring engine')}</small></div><strong>${n(f.count)} <small>hits</small></strong></div>`).join('')}</div>`:empty('No detection signals recorded','Symbols detected during real scans will be ranked here.');}
function senderTable(){const top=topSenders();return top.length?`<div class="signals-ranked">${top.map((f,i)=>`<div class="ranked-row"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><div><b>${esc(f.domain)}</b><small>${n(f.count)} observed messages</small></div><strong>${n(f.flagged)} <small>flagged</small></strong></div>`).join('')}</div>`:empty('No sender intelligence yet','Domain patterns are calculated from locally retained message history.');}
function engineRows(){
 const rows=[['rspamd_http','Rspamd HTTP','38471'],['milter','Milter','38472'],['smtp','SMTP relay filter','38473'],['controller','Training controller','38474']];
 const svc=S.runtime?.services||{};
 return `<div class="engine-rows">${rows.map(([key,label,port])=>`<div class="engine-row"><span class="engine-indicator ${svc[key]?.enabled?'available':'off'}" aria-hidden="true"></span><div><b>${label}</b><small>${esc(svc[key]?.address||(!S.runtime?'Status unavailable':'Default '+port+' · disabled'))}</small></div><span class="engine-state">${!S.runtime?'Unverified':svc[key]?.enabled?'Configured':'Disabled'}</span></div>`).join('')}</div>`;
}

function dashboard(){
 const c=S.stats?.actions||{};
 const f=getQueue();
 const total=n(S.stats?.total);
 const latest=S.messages.slice(0,7);
 return `${heading('Mail defense command center','Investigate decisions, control containment and tune scoring from one operational workspace.', '<a class="secondary" href="/scan-workbench" data-route="scanlab">Open scan workbench →</a>')}
 ${configurationStatus()}
 <section class="tactical-stats" aria-label="Mail defense statistics">
   <div class="tactical-lead"><span>Analyzed / Retained</span><strong>${total}</strong><small>All retained verdicts · not a lifetime counter</small></div>
   <div class="tactical-stat"><span>Rejected</span><strong class="tone-danger">${n(c.reject)}</strong><small>Rejected at scoring</small></div>
   <div class="tactical-stat"><span>Quarantine verdicts</span><strong class="tone-amber">${n(c.quarantine)}</strong><small>${n(f.length)} originals currently held in recent history</small></div>
   <div class="tactical-stat"><span>Accepted</span><strong>${n(c.accept)}</strong><small>${n(c.tag)} tagged for review</small></div>
   <div class="tactical-policy"><span>Enforcement levels</span><p>Tag <b>${esc(S.config?.settings?.tag_threshold??5)}</b> · Hold <b>${esc(S.config?.settings?.quarantine_threshold??10)}</b> · Reject <b>${esc(S.config?.settings?.reject_threshold??20)}</b></p><a href="/policy" data-route="settings">Adjust thresholds →</a></div>
 </section>
 <div class="command-grid">
   <section class="activity-region"><div class="region-head"><div><span class="section-index">01 / RESPONSE</span><h2>Priority mail decisions</h2></div><a href="/investigations" data-route="investigate">Open investigations →</a></div><div class="activity-note">Recent observed messages · select an item for score evidence and audited action</div>${previewRows([...S.messages].sort((a,b)=>((b.action==='quarantine'||b.action==='reject')?1:0)-((a.action==='quarantine'||a.action==='reject')?1:0)),7)}</section>
   <aside class="control-rail"><section class="control-zone"><div class="region-head"><div><span class="section-index">02 / CONTAINMENT</span><h2>Quarantine</h2></div><a href="/quarantine" data-route="quarantine">View held →</a></div><div class="queue-figure"><strong>${n(f.length)}</strong><span>stored originals requiring review</span></div><p>Only mail physically held by SpamGate's SMTP filter can be released. A quarantine *verdict* from a test scan is not held mail.</p>${f.length?`<button class="primary" data-inspect="${esc(f[0].id)}">Review next held message →</button>`:'<a class="text-link" href="/connections" data-route="connect">Configure a mail filtering transport →</a>'}</section>
    <section class="control-zone"><div class="region-head"><div><span class="section-index">03 / DETECTION</span><h2>Top triggered signals</h2></div><a href="/signals" data-route="signals">Manage →</a></div>${signalTable()}</section></aside>
 </div>
 <div class="analysis-grid"><section class="analysis-region"><div class="region-head"><div><span class="section-index">04 / VERDICT MIX</span><h2>Disposition profile</h2></div><span class="data-scope">Latest ${n(S.messages.length)} visible records</span></div>${verdictBars()}</section><section class="analysis-region"><div class="region-head"><div><span class="section-index">05 / INFRASTRUCTURE</span><h2>Listener configuration</h2></div><a href="/connections" data-route="connect">Configure →</a></div>${engineRows()}<p class="data-caveat">Configured ≠ connected. A listener being enabled does not verify real MTA traffic.</p></section></div>`;
}


function quarantine(){
 const q=S.search.toLowerCase();
 const held=getQueue().filter(m=>[m.subject,m.sender,(m.recipients||[]).join(' '),m.id].join(' ').toLowerCase().includes(q));
 return `${heading('Quarantine control','Review stored originals and release or permanently discard mail held by the SMTP filtering path.')}
 <div class="work-banner"><strong>${n(held.length)}</strong><div><b>Stored messages available for review</b><p>These are originals retained by the SMTP filter, not hypothetical scores. Release requires a configured outbound relay and confirmation.</p></div></div>
 <div class="task-filter"><label for="search">Find held mail</label><input id="search" type="search" placeholder="Search sender, recipient or subject" value="${esc(S.search)}"/><span>${n(held.length)} matching items</span></div>
 ${held.length?previewRows(held,1000):empty('No stored mail in quarantine','Nothing is currently held in the visible history. A message scored as “quarantine” in an advisory scan has not been intercepted or stored for release.')}
 <div class="ops-footnote"><b>Retention note:</b> Only the latest 1,000 records are loaded in this view. Administrators can export complete retained history from Mail activity.</div>`;
}
function investigate(){
 const q=S.search.toLowerCase();
 const threshold=Number(S.config?.settings?.tag_threshold||5);
 const cases=S.messages.filter(m=>(S.filterAction==='all'||m.action===S.filterAction)&&([m.subject,m.sender,m.client_ip,m.id,(m.recipients||[]).join(' ')].join(' ').toLowerCase().includes(q)));
 const flagged=cases.filter(m=>['reject','quarantine','tag'].includes(m.action)||Number(m.score)>=threshold);
 return `${heading('Investigations','Examine suspicious mail, trace scoring evidence, record overrides, and train classifiers with verified samples.')}
 <div class="investigation-intro"><div><strong>${n(flagged.length)}</strong><span>flagged decisions in current result set</span></div><div><strong>${n(cases.filter(m=>m.override_by).length)}</strong><span>recorded manual overrides</span></div><div><strong>${n(cases.filter(m=>m.findings?.length>0).length)}</strong><span>messages with evidence</span></div></div>
 <div class="task-filter"><label for="search">Search observations</label><input id="search" type="search" placeholder="Sender, subject, recipient, IP or message ID" value="${esc(S.search)}"/><label for="action-filter">Decision</label><select id="action-filter">${['all','reject','quarantine','tag','accept'].map(v=>`<option value="${v}" ${v===S.filterAction?'selected':''}>${v==='all'?'All verdicts':v}</option>`).join('')}</select></div>
 <div class="region-head"><div><span class="section-index">FORENSIC RECORDS</span><h2>Flagged mail</h2></div><span class="data-scope">${n(flagged.length)} matches · latest ${n(S.messages.length)} loaded</span></div>
 ${flagged.length?previewRows(flagged,1000):empty('No suspicious verdicts found','Change the filters or review all mail activity. This view only uses actual stored scan records.')}
 <div class="region-head lower-region"><div><span class="section-index">ATTRIBUTION</span><h2>Most frequent evidence</h2></div><a href="/signals" data-route="signals">Signal controls →</a></div>${signalTable()}`;
}
function threats(){
 const enabled=(S.config?.dns_lists||[]).filter(x=>x.enabled).length;
 return `${heading('Threat intelligence','Operational reputation and detection evidence aggregated from retained mail, configured lists and scoring policies.')}
 <div class="intel-statbar"><div><span>Custom rules</span><strong>${n(S.config?.rules?.filter(r=>r.enabled).length)}</strong><small>active matching policies</small></div><div><span>DNS reputation</span><strong>${n(enabled)}</strong><small>active zones</small></div><div><span>Detection symbols</span><strong>${n(S.signals?.filter(d=>d.enabled).length)}</strong><small>enabled detectors</small></div><div><span>Learning</span><strong>${S.bayesStats?.ready?'Active':'Collecting'}</strong><small>Bayesian corpus status</small></div></div>
 <div class="analysis-grid"><section class="analysis-region"><div class="region-head"><div><span class="section-index">SENDER ANALYSIS</span><h2>Domains producing flagged mail</h2></div><a href="/messages" data-route="history">All mail →</a></div>${senderTable()}<p class="data-caveat">Calculated from the most recent ${n(S.messages.length)} locally visible message records. A sender domain alone is not proof of maliciousness.</p></section><section class="analysis-region"><div class="region-head"><div><span class="section-index">SIGNAL FREQUENCY</span><h2>Evidence leaderboard</h2></div><a href="/signals" data-route="signals">Detector settings →</a></div>${signalTable()}</section></div>
 <section class="threat-actions"><div><span class="section-index">MITIGATION PLAYBOOK</span><h2>Control the next decision</h2><p>Set permanent scoring rules, change signal weights, tune DNS reputation or train adaptive filters. Every change affects subsequent scans, not already-delivered mail.</p></div><div class="threat-links"><a href="/rules" data-route="rules">Manage blocking and allow rules <span>→</span></a><a href="/blocklists" data-route="lists">Manage DNS reputation zones <span>→</span></a><a href="/learning" data-route="learning">Train Bayesian / fuzzy / neural models <span>→</span></a><a href="/policy" data-route="settings">Review enforcement thresholds <span>→</span></a></div></section>`;
}
function scanlab(){return `${heading('Scan workbench','Submit an RFC 5322 message through SpamGate to inspect the real scoring pipeline. This does not deliver email.')}
 <div class="lab-grid"><div class="lab-intro"><span class="section-index">ADVISORY SCAN</span><h2>Test before enforcing.</h2><p>Import a legitimate .eml specimen you are permitted to inspect. SpamGate evaluates its rules and detection symbols and records the result in message history for investigation.</p><div class="lab-warning">A scan verdict is only advice until an MTA enforces it. This tool does not quarantine a raw email file or release mail on another system.</div><a href="/connections" data-route="connect">Mail server integration documentation →</a></div><section class="panel"><h2>Analyze raw email</h2><form id="scan-form"><div class="field"><label for="scan-file">Original email (.eml, max 10 MiB)</label><input id="scan-file" name="eml" type="file" accept=".eml,message/rfc822" required></div><div class="field"><label for="scan-sender">SMTP envelope sender</label><input id="scan-sender" name="sender" placeholder="sender@example.com"></div><div class="field"><label for="scan-recipient">Recipient address</label><input id="scan-recipient" name="recipients" placeholder="recipient@example.com"></div><div class="field"><label for="scan-ip">Remote sender IP (optional)</label><input id="scan-ip" name="client_ip" placeholder="203.0.113.10"></div><button class="primary" type="submit">Analyze message →</button></form></section></div>`;}

function messageHistory(){const q=S.search.toLowerCase();const isRemote=!!S.historyResults;const filtered=isRemote?S.historyResults.items:(S.messages.filter(m=>(S.filterAction==='all'||m.action===S.filterAction)&&[m.sender,m.subject,m.action,(m.recipients||[]).join(' '),m.id].join(' ').toLowerCase().includes(q)));const total=isRemote?S.historyResults.total:S.messages.length;return `${heading('The message ledger.','Search all retained history, including entries outside the recent 1,000-message window.',S.me.role==='admin'?'<a class="secondary" href="/api/v1/export" download>Export JSONL</a>':'')}<div class="history-tools"><div class="search-row"><input id="search" aria-label="Search messages" placeholder="Sender, recipient, subject, message ID…" value="${esc(S.search)}"><select id="action-filter" aria-label="Filter by verdict">${['all','accept','tag','quarantine','reject'].map(k=>`<option value="${k}" ${S.filterAction===k?'selected':''}>${k==='all'?'All verdicts':k}</option>`).join('')}</select><button class="secondary" id="search-full">Search retained history</button><button class="secondary" id="reload">Refresh</button></div><div class="history-count">${isRemote?'All retained history':'Recent records'} · Showing ${n(filtered.length)} of ${n(total)} matching records</div></div>${table(filtered||[])}${isRemote?`<div class="form-actions"><button class="secondary" id="search-prev" ${S.historyOffset===0?'disabled':''}>Previous</button><span>${n(S.historyOffset+1)}–${n(Math.min(S.historyOffset+50,total))} of ${n(total)}</span><button class="secondary" id="search-next" ${S.historyOffset+50>=total?'disabled':''}>Next</button></div>`:''}`}
function rules(){const items=S.config?.rules||[];const admin=S.me.role==='admin';const edit=S.editRule;const kinds=admin?['sender_email','sender_domain','recipient_email','client_ip','subject_contains','body_contains','url_domain','header_contains']:['sender_email','sender_domain'];return `${heading('Scoring rules.','Create, edit, suspend and expire exact match rules. Changes apply to new messages; existing verdict history is preserved.')}<div class="split"><section class="panel"><h2>${edit?'Edit existing rule':admin?'Create scoring rule':'My sender policy'}</h2><form id="rule-form"><div class="field"><label>Rule name<input name="name" required maxlength="100" value="${esc(edit?.name||'')}"></label></div><div class="field"><label>Match against<select name="kind">${kinds.map(x=>`<option value="${x}" ${edit?.kind===x?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}</select></label></div><div class="field"><label>Match value<input name="value" required maxlength="256" value="${esc(edit?.value||'')}"></label></div>${admin?`<div class="field"><label>Weight (−100 to +100)<input name="score" type="number" min="-100" max="100" step="0.1" value="${Number(edit?.score??5)}" required></label></div><div class="field"><label>Priority (−1000 to 1000)<input name="priority" type="number" min="-1000" max="1000" value="${Number(edit?.priority||0)}"></label></div>`:''}<div class="field"><label>Expires (optional)<input name="expires_at" type="datetime-local" value="${edit?.expires_at?esc(edit.expires_at.slice(0,16)):''}"></label></div><div class="field"><label>Action override<select name="action">${(admin?['','accept','tag','quarantine','reject']:['accept','quarantine']).map(x=>`<option value="${x}" ${edit?.action===x?'selected':''}>${x||'None — use weight'}</option>`).join('')}</select></label></div><div class="form-actions"><button type="submit" class="primary">${edit?'Save changes':'Add rule'}</button>${edit?'<button type="button" class="secondary" id="cancel-rule-edit">Cancel</button>':''}</div></form></section><section><div class="section-head"><h2>Rulebook <small>(${items.filter(x=>x.enabled).length} active)</small></h2></div>${items.length?`<div class="table-shell"><table><thead><tr><th>Rule and status</th><th>Criteria</th><th>Weight</th><th>Actions</th></tr></thead><tbody>${items.map(x=>`<tr><td><b>${esc(x.name)}</b><div class="hint">${x.enabled?'Enabled':'Disabled'} · Priority ${n(x.priority)}${x.expires_at?' · Expires '+esc(fmtDate(x.expires_at)):''}</div></td><td>${esc(x.kind)}<div>${esc(x.value)}</div></td><td class="mono">${Number(x.score).toFixed(1)}</td><td><div class="form-actions"><button class="secondary" data-edit-rule="${esc(x.id)}">Edit</button><button class="secondary" data-toggle-rule="${esc(x.id)}">${x.enabled?'Disable':'Enable'}</button><button class="danger" data-delete-rule="${esc(x.id)}">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('No custom rules.','Create a rule to define a matching condition and score.')}</section></div>`}
function lists(){const lists=S.config?.dns_lists||[];return `${heading('DNS blocklists.','Use licensed, administrator-selected DNSBL providers. Queries are off by default to avoid unapproved external lookups.')}<div class="note"><b>Operational note:</b> The query resolver sends sender IP-derived DNS queries to configured list providers. Confirm usage terms before enabling any public service.</div><div class="split"><section class="panel"><h2>Add a DNSBL provider</h2><form id="dns-form"><div class="field"><label>DNS zone</label><input name="zone" required placeholder="dnsbl.provider.example"></div><div class="field"><label>Score if listed</label><input name="score" type="number" step="0.1" min="-100" max="100" value="5" required></div><div class="toggle"><input type="checkbox" id="dns-enabled" name="enabled"><label for="dns-enabled">Enable this provider</label></div><button class="primary">Add provider</button></form></section><section><div class="section-head"><h2>Configured providers</h2></div>${lists.length?`<div class="table-shell"><table><thead><tr><th>Zone</th><th>Weight</th><th>Status</th><th></th></tr></thead><tbody>${lists.map(v=>`<tr><td class="mono">${esc(v.zone)}</td><td class="mono">${Number(v.score).toFixed(1)}</td><td>${v.enabled?'Active':'Disabled'}</td><td><button class="danger" data-delete-dns="${esc(v.zone)}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:empty('No DNS providers configured.','Add a provider, then enable lookups under Policy settings.')}</section></div>`}
function users(){const us=S.config?.users||[];return `${heading('Mailboxes and access.','Create restricted accounts for supported, explicitly mapped mailboxes. Each user only sees their own recipients and can manage personal sender overrides.')}<div class="split"><section class="panel"><h2>Add mailbox account</h2><form id="user-form"><div class="field"><label>Username</label><input name="name" required minlength="3" maxlength="48" autocomplete="off"></div><div class="field"><label>Exact mailbox address</label><input name="email" required type="email" placeholder="person@example.com"></div><div class="field"><label>Temporary password</label><input name="password" required type="password" minlength="12" autocomplete="new-password"></div><button class="primary">Create mailbox account</button></form><p class="hint">Native LDAP, OIDC and mail-server directory synchronization are planned but not implemented in this release.</p></section><section><h2>Account directory</h2><div class="table-shell"><table><thead><tr><th>Account</th><th>Mailbox</th><th>Access</th><th></th></tr></thead><tbody>${us.map(v=>`<tr><td><b>${esc(v.name)}</b></td><td>${esc(v.email||'—')}</td><td>${esc(v.role)}</td><td>${v.role==='admin'?'Protected':`<button class="danger" data-delete-user="${esc(v.name)}">Remove</button>`}</td></tr>`).join('')}</tbody></table></div></section></div>`}
function tokens(){const ts=S.config?.tokens||[];return `${heading('API access.','Issue scoped integration keys for mail systems and custom applications. Keys are SHA-256 hashed at rest and shown only when created.')}<div class="split"><section class="panel"><h2>Create an integration key</h2><form id="token-form"><div class="field"><label>Purpose / integration name</label><input name="name" required placeholder="Exim production scanner"></div><div class="field"><label>Permission</label><select name="scope"><option value="scan">Scan messages only</option><option value="admin">Full administrator API</option></select></div><button class="primary">Generate key</button></form>${S.onceToken?`<div class="note" role="status"><b>Copy this key now. It will not be shown again.</b><div class="codeblock" style="user-select:all">${esc(S.onceToken)}</div><button class="secondary" id="copy-token">Copy key</button></div>`:''}</section><section><h2>Issued keys</h2>${ts.length?`<div class="table-shell"><table><thead><tr><th>Integration</th><th>Scope</th><th>Created</th><th></th></tr></thead><tbody>${ts.map(v=>`<tr><td>${esc(v.name)}</td><td>${esc(v.scope)}</td><td>${esc(fmtDate(v.created))}</td><td><button class="danger" data-delete-token="${esc(v.name)}">Revoke</button></td></tr>`).join('')}</tbody></table></div>`:empty('No integration keys issued.','Generate a scan-scoped key to connect mail systems without granting management privileges.')}</section></div>`}
function settings(){const x=S.config?.settings||{};return `${heading('Policy settings.','Set the score thresholds that separate clean, suspicious, quarantined and rejected mail, then manage data retention.')}<div class="panel" style="max-width:850px"><h2>Enforcement thresholds</h2><form id="settings-form"><div class="field"><label>Installation name</label><input name="site_name" value="${esc(x.site_name)}" required></div><div class="fields"><div class="field"><label>Flag / tag at</label><input type="number" step="0.1" min="0" name="tag_threshold" value="${esc(x.tag_threshold)}" required></div><div class="field"><label>Quarantine at</label><input type="number" step="0.1" name="quarantine_threshold" value="${esc(x.quarantine_threshold)}" required></div><div class="field"><label>Reject at</label><input type="number" step="0.1" name="reject_threshold" value="${esc(x.reject_threshold)}" required></div><div class="field"><label>Message history retention (days)</label><input type="number" min="1" max="3650" name="retention_days" value="${esc(x.retention_days)}" required></div><div class="field"><label>Maximum history records</label><input type="number" min="100" max="500000" name="max_history" value="${esc(x.max_history)}" required></div></div><div class="toggle"><input type="checkbox" id="dnsbl-enabled-global" name="dnsbl_enabled" ${x.dnsbl_enabled?'checked':''}><label for="dnsbl-enabled-global">Enable external DNS blocklist lookups</label></div><p class="hint">Rule weights remain individually configurable. Stronger actions take effect on subsequent scans.</p><button class="primary">Save policy</button></form></div>`}
function connect(){const h=S.hostReport;const native=h&&h.platform==='linux';const integration=h?.integration||'unidentified';return `${heading('Mail server integration.','Native on the mail server is the preferred deployment. Docker and remote filtering are optional, not required.')}<div class="note"><b>Local system:</b> ${h?`${esc(h.panel==='none'?'No hosting panel detected':h.panel)} · ${esc(h.mail_server)} · ${esc(integration)}`:'Host inventory unavailable. Only the admin can inspect local MTA settings.'}<br><span class="hint">Configuration inspection does not establish production mail protection.</span></div><div class="split"><section class="panel"><h2>1. Existing Linux mail server</h2><p>Install the standalone SpamGate binary under systemd. New native installations can open a loopback Milter on port <code>38472</code> without changing Postfix or any hosting-panel configuration.</p><pre class="codeblock">sudo ./install-linux.sh
sudo /usr/local/bin/spamgate -mailserver-report
sudo /usr/local/libexec/spamgate/configure-postfix --preview</pre><p class="hint">Automatic Postfix attachment is opt-in and available only on unmanaged Postfix. No cPanel, ISPConfig, Plesk or DirectAdmin files are rewritten.</p>${h?`<div class="note"><b>Local Milter connection:</b> ${h.milter_ready?'TCP port answers':'not reachable on loopback'}<br><b>Existing Postfix milters:</b> ${esc(h.existing_milters||'None reported')}<br><b>Proposed Postfix setting:</b> ${esc(h.proposed_milters||'Requires inspection')}<br>${(h.notes||[]).map(x=>`<span class="hint">${esc(x)}</span>`).join('<hr>')}</div>`:''}</section><section class="panel"><h2>2. Integration by mail server</h2><p><b>Postfix / ISPConfig:</b> local Milter. ISPConfig-managed hosts require a panel-safe persistent configuration method.</p><p><b>cPanel / WHM:</b> uses Exim, not Postfix. A verified Exim ACL/spamd adapter is still outstanding; running SpamGate locally alone does not filter cPanel mail.</p><p><b>Custom MTAs:</b> send full RFC 5322 mail to the authenticated scan API and enforce its returned decision. HTTP scans alone do not quarantine original mail.</p><p><b>Remote/Docker:</b> use a private network and dedicated Milter/SMTP/HTTP listener only when needed.</p><a href="https://github.com/gigabytegrove/spamgate/blob/main/docs/NATIVE_MAIL_SERVERS.md" target="_blank" rel="noopener noreferrer">Native integration instructions ↗</a></section></div><section class="panel"><h2>3. Diagnostic checks</h2><p>These report the local daemon's configuration and relay reachability, not actual end-to-end message delivery. Always send controlled test mail before production integration.</p><button class="secondary" id="test-integration">Test configured relay</button>${S.diagnostics?`<pre class="codeblock">${esc(JSON.stringify(S.diagnostics,null,2))}</pre>`:''}</section>`}

function docs(){return `${heading('Documentation.','Operational basics, rule evaluation, privacy defaults and supported integration paths.')}<div class="split"><section class="panel"><h2>Decision lifecycle</h2><p>Each message enters a connector, is parsed, then scored by built-in content/header/attachment/URL checks, custom weighted rules and (optionally) DNSBL checks. Findings include symbols, evidence, source and numeric weight.</p><p><b>accept</b> → <b>tag</b> → <b>quarantine</b> → <b>reject</b> as the thresholds increase. An explicit administrator-defined rule action can take precedence.</p><h3>History and privacy</h3><p>Built-in signal weights and enabled states can be changed under Built-in signals. Scan metadata is written to an on-disk event journal. The full message is not stored by default. Original mail is stored with restrictive permissions only when the SMTP connector quarantines a message.</p></section><section class="panel"><h2>Administration</h2><p>Admin users manage global scoring, accounts, blocklists and API keys. Mailbox users see only messages addressed to their exact mailbox and can force allow/quarantine for their own single-recipient sender matches.</p><h3>Release from quarantine</h3><p>For SMTP-held messages, select the message in History, then choose Release. SpamGate sends the stored original to the configured upstream SMTP server and audits the operation.</p><h3>Project documentation</h3><p>See the repository's <code>docs/</code> directory for deployment, REST API, protocol support, security, architecture and the complete compatibility roadmap.</p></section></div>`}
function detailView(m){
  const a=S.me.role==='admin';
  const evidence=(m.findings||[]).length?(m.findings||[]).map(f=>`<div class="finding"><div class="weight">${Number(f.score)>=0?'+':''}${Number(f.score).toFixed(2)}</div><div><div class="symbol">${esc(f.symbol)}</div><div class="source">${esc(f.source)}</div></div><div class="detail">${esc(f.detail)}</div></div>`).join(''):empty('No scoring signals matched.','No enabled detector assigned a nonzero finding.');
  return `<div class="detail-layer" id="detail-layer"><section class="detail-panel" role="dialog" aria-modal="true" aria-labelledby="inspect-title" tabindex="-1"><button class="icon-button detail-close" id="close-detail" aria-label="Close message details">×</button><div class="hero-rule">DECISION RECORD / ${esc(m.id.slice(0,12))}</div><h2 id="inspect-title">${esc(m.subject||'(no subject)')}</h2><div class="detail-summary">${action(m.action)}<span class="detail-score">${Number(m.score)>0?'+':''}${Number(m.score).toFixed(2)} <small>points</small></span></div><dl class="info-grid"><dt>Received</dt><dd>${esc(fmtDate(m.timestamp))}</dd><dt>Envelope sender</dt><dd>${esc(m.sender||'—')}</dd><dt>Recipients</dt><dd>${esc((m.recipients||[]).join(', ')||'—')}</dd><dt>Originating client IP</dt><dd>${esc(m.client_ip||'Not supplied')}</dd><dt>Receiving mail server</dt><dd>${esc(m.ingest_ip||'Not supplied')}</dd><dt>Connector</dt><dd>${esc(m.connector)}</dd><dt>Message ID</dt><dd>${esc(m.message_id||'—')}</dd><dt>Delivery status</dt><dd>${esc(m.delivery||'Advisory scan only')}</dd><dt>Initial decision</dt><dd>${esc(m.original_action||'Not overridden')}</dd><dt>Changed by</dt><dd>${esc(m.override_by||'—')}</dd><dt>Override justification</dt><dd>${esc(m.override_reason||'—')}</dd></dl><div class="section-head"><h2>Why this verdict?</h2><span class="mono">${n(m.findings?.length||0)} findings</span></div>${evidence}${a&&m.delivery==='quarantined'?`<div class="section-head"><h2>Quarantine preview</h2></div><button class="secondary" id="preview-quarantine">Show raw-text preview</button><p class="hint">Plain text only · first 4 KiB · no remote images or active content</p>${S.preview?`<pre class="codeblock" id="preview-text" tabindex="-1">${esc(S.preview.preview)}</pre>`:''}`:''}${a?`<div class="section-head"><h2>Override the decision</h2></div><p class="section-caption">Changes are audited and do not recall mail already delivered or rejected.</p><form id="override-form"><div class="field"><label for="override-action">New verdict</label><select id="override-action" name="action">${['accept','tag','quarantine','reject'].map(x=>`<option value="${x}" ${m.action===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="override-reason">Reason for change</label><textarea id="override-reason" name="reason" required minlength="5" maxlength="500" placeholder="Document exactly why the verdict was changed"></textarea></div><div class="form-actions"><button type="submit" class="primary">Save audited decision</button>${m.delivery==='quarantined'?'<button class="secondary" type="button" id="release">Release held mail</button><button class="danger" type="button" id="discard-quarantine">Permanently discard</button>':''}</div></form><div class="section-head"><h2>Confirm for learning</h2></div><p class="section-caption">Use only verified labels. Training changes future scoring, not this recorded decision.</p><div class="form-actions"><button class="secondary" type="button" data-neural-label="spam">Confirmed spam</button><button class="secondary" type="button" data-neural-label="ham">Confirmed legitimate</button></div>`:''}</section></div>`;
}

function signals(){const admin=S.me.role==='admin';return `${heading('Built-in signals.','Manage the detection weight and enabled state of every built-in check. The effective score is recorded alongside its origin in each message.')}<div class="note">Changes affect subsequent scans only; past decisions remain in the audit history. Built-in detectors recognize patterns — this control changes scoring, not their underlying match conditions.</div><div class="table-shell"><table><thead><tr><th>Symbol / detection</th><th>Family</th><th>Default</th><th>Effective policy</th></tr></thead><tbody>${(S.signals||[]).map(d=>`<tr><td><b class="mono">${esc(d.symbol)}</b><div class="hint">${esc(d.description)}</div></td><td>${esc(d.source)}</td><td class="mono">${Number(d.default_score).toFixed(2)}</td><td><form class="signal-form" data-symbol="${esc(d.symbol)}"><div class="form-actions" style="margin:0"><label class="field" style="margin:0">Weight <input style="max-width:100px" name="score" type="number" min="-100" max="100" step="0.1" required value="${Number(d.score)}" ${admin?'':'disabled'}></label><label class="field" style="margin:0">Enabled <input name="enabled" type="checkbox" ${d.enabled?'checked':''} ${admin?'':'disabled'}></label>${admin?'<button type="submit" class="secondary">Save signal</button>':''}</div></form></td></tr>`).join('')}</tbody></table></div>`}
function learning(){const x=S.bayesStats||{};return `${heading('Train the filter.','Curate a local spam and legitimate-mail corpus. Training persists on disk and is only available to administrators.')}<div class="metrics"><div class="metric"><div class="metric-label">Trained spam</div><div class="metric-value">${n(x.spam)}</div></div><div class="metric"><div class="metric-label">Trained legitimate mail</div><div class="metric-value">${n(x.ham)}</div></div><div class="metric"><div class="metric-label">Known terms</div><div class="metric-value">${n(x.terms)}</div></div><div class="metric"><div class="metric-label">Classifier readiness</div><div class="metric-value" style="font-size:1.3rem">${x.ready?'Active':'Collecting'}</div></div></div><section class="panel"><h2>Train from an email</h2><p>Upload an original RFC 5322 .eml message that you have manually classified. SpamGate stores word counts and document frequencies, not the message body. At least 10 spam and 10 legitimate training samples are required before the classifier influences scores.</p><form id="bayes-form"><div class="fields"><div class="field"><label for="training-eml">Message to learn</label><input id="training-eml" name="eml" type="file" accept=".eml,message/rfc822" required></div><div class="field"><label for="training-label">Confirmed classification</label><select id="training-label" name="label" required><option value="spam">Unwanted or malicious (spam)</option><option value="ham">Wanted, legitimate email (ham)</option></select></div></div><button class="primary" type="submit">Train classifier</button></form><p class="fine-print">Train only from messages you are authorized to inspect. Do not upload private mail without permission. Mislabelled samples can poison classification. This first version supports additive training; sample-level unlearning is not implemented.</p></section><div class="section-head"><h2>Fuzzy reputation</h2></div><div class="metrics"><div class="metric"><div class="metric-label">Near-duplicate spam patterns</div><div class="metric-value">${n(S.fuzzyStats?.spam)}</div></div><div class="metric"><div class="metric-label">Near-duplicate safe patterns</div><div class="metric-value">${n(S.fuzzyStats?.ham)}</div></div></div><section class="panel"><h2>Add a reference message</h2><p>Train a near-duplicate fingerprint with a confirmed .eml sample. Stored signatures expire after 90 days and can be removed below. The engine stores a content fingerprint, not the original email.</p><form id="fuzzy-form"><div class="fields"><div class="field"><label for="fuzzy-eml">Reference email (.eml)</label><input id="fuzzy-eml" name="eml" type="file" accept=".eml,message/rfc822" required></div><div class="field"><label for="fuzzy-label">Classification</label><select id="fuzzy-label" name="label" required><option value="spam">Confirmed spam</option><option value="ham">Confirmed legitimate mail</option></select></div></div><button type="submit" class="primary">Save fingerprint</button></form><p class="fine-print">At least 18 words are needed. Fingerprints are compared using SimHash with a strict length limit; similarity is supporting evidence, not a guarantee of malicious content.</p></section>${S.fuzzyEntries?.length?`<div class="table-shell"><table><thead><tr><th>Fingerprint ID</th><th>Label</th><th>Shingles</th><th>Added</th><th>Manage</th></tr></thead><tbody>${S.fuzzyEntries.map(e=>`<tr><td class="mono">${esc(e.id.slice(0,12))}</td><td>${esc(e.label)}</td><td>${n(e.shingles)}</td><td>${esc(fmtDate(e.created))}</td><td><button class="danger" data-fuzzy-delete="${esc(e.id)}">Delete</button></td></tr>`).join('')}</tbody></table></div>`:empty('No fuzzy fingerprints trained.','Add a manually confirmed reference email to begin near-duplicate matching.')}<div class="section-head"><h2>Local neural learning</h2></div><div class="metrics"><div class="metric"><div class="metric-label">Confirmed spam messages</div><div class="metric-value">${n(S.neuralStats?.spam)}</div></div><div class="metric"><div class="metric-label">Confirmed legitimate messages</div><div class="metric-value">${n(S.neuralStats?.ham)}</div></div><div class="metric"><div class="metric-label">Model state</div><div class="metric-value" style="font-size:1.3rem">${S.neuralStats?.ready?'Scoring':'Collecting'}</div></div></div><section class="panel"><h2>Train from decision history</h2><p>Open a message under Message history, review its evidence, then choose <b>Confirm as spam</b> or <b>Confirm as legitimate</b>. The small CPU-only neural network learns combinations of scoring symbols, not raw email text. It starts scoring after 10 confirmed examples of each class.</p><p class="fine-print">Manual labels only. No automated feedback loop. This experimental classifier is not interchangeable with Rspamd neural model files. Re-training with the same message ID is idempotent.</p><button class="secondary" data-section="history">Review message history →</button></section>`}
function deliveryQueue(){
 const q=S.deliveryQueue;
 if(!q || q.enabled===false)return `${heading('Delivery queue.','Durable store-and-forward SMTP delivery is not enabled.')}${empty('No durable delivery queue active.','Configure an SMTP listener and relay; the on-disk delivery queue is enabled unless explicitly disabled.')}`;
 const jobs=q.jobs||[];
 return `${heading('Delivery queue.','Inspect unsent originals, retry failed relays, and control dead-letter retention. The SMTP client has already received its acknowledgment for queued mail.')}<section class="tactical-stats"><div class="tactical-stat"><span>Waiting / retry</span><strong>${n(q.queued)}</strong></div><div class="tactical-stat"><span>In flight</span><strong>${n(q.delivering)}</strong></div><div class="tactical-stat"><span>Dead letters</span><strong class="tone-danger">${n(q.dead)}</strong></div><div class="tactical-stat"><span>Originals on disk</span><strong>${n(q.total)}</strong></div></section><div class="note"><b>Delivery guarantee:</b> At-least-once. A crash after the remote SMTP server accepts mail can result in a duplicate on retry. Inspect logs before manually retrying uncertain deliveries.</div>${jobs.length?`<div class="table-shell"><table><thead><tr><th>Queued message</th><th>Recipients</th><th>State</th><th>Attempts / next try</th><th>Controls</th></tr></thead><tbody>${jobs.map(x=>`<tr><td><b>${esc(x.subject||'No subject')}</b><small class="rule-type">${esc(x.sender)}</small><div class="hint">${esc(x.last_error||'No relay errors recorded')}</div></td><td>${esc((x.recipients||[]).join(', '))}</td><td>${esc(x.state)}</td><td>${n(x.attempts)}<div class="hint">${esc(fmtDate(x.next_attempt))}</div></td><td><div class="form-actions"><button type="button" class="secondary" data-queue-retry="${esc(x.id)}" ${x.state==='delivering'?'disabled':''}>Retry</button><button type="button" class="danger" data-queue-discard="${esc(x.id)}" ${['delivering','delivered'].includes(x.state)?'disabled':''}>Discard</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('No pending deliveries.','The outbox has no queued or dead-letter originals.')}`
}
async function runHistorySearch(offset=0){
 const params=new URLSearchParams({q:S.search,action:S.filterAction,offset:String(offset),limit:'50'});
 S.historyResults=await api('/api/v1/history/search?'+params.toString());S.historyOffset=offset;render();
}
function render(){const app=$('#app');if(!S.authenticated){app.innerHTML=authLayout();return}const views={overview:dashboard,investigate,quarantine,threats,scanlab,history:messageHistory,delivery:deliveryQueue,rules,signals,learning,lists,users,tokens,settings,connect,docs};app.innerHTML=layout((views[S.section]||dashboard)());document.title=`${(navigation.find(x=>x[0]===S.section)||navigation[0])[1]} | SpamGate`}
window.addEventListener('popstate',()=>{const requested=sectionFromLocation();S.section=permitted(requested)?requested:'overview';S.inspect=null;render()});
document.addEventListener('click',async event=>{const el=event.target.closest('button,[data-section],[data-route]');if(!el)return;const id=el.id;try{
  if(el.dataset.route){event.preventDefault();routeTo(el.dataset.route);return}if(id==='retry'){start();return}if(id==='nav-toggle'){S.menu=!S.menu;render();return}if(el.dataset.section){routeTo(el.dataset.section);return}
  if(id==='reload'){await refresh();alertUser('Message history refreshed');return}
  if(id==='search-full'){await runHistorySearch(0);return}
  if(id==='test-integration'){S.diagnostics=await api('/api/v1/integrations/diagnostics');render();return}
  if(id==='search-next'){await runHistorySearch(S.historyOffset+50);return}
  if(id==='search-prev'){await runHistorySearch(Math.max(0,S.historyOffset-50));return}
  if(el.dataset.queueRetry){if(!confirm('Attempt delivery of this queued message now? A previous uncertain SMTP result could cause duplicate delivery.'))return;await api('/api/v1/delivery-queue/'+encodeURIComponent(el.dataset.queueRetry)+'/retry',{method:'POST'});await refresh();alertUser('Queued delivery scheduled');return}
  if(el.dataset.queueDiscard){if(!confirm('Permanently discard this queued original? It cannot be recovered or delivered.'))return;await api('/api/v1/delivery-queue/'+encodeURIComponent(el.dataset.queueDiscard),{method:'DELETE',headers:{'X-Confirm-Discard':'discard queued original'}});await refresh();alertUser('Queued original discarded');return}
  if(el.dataset.editRule){S.editRule=(S.config?.rules||[]).find(x=>x.id===el.dataset.editRule)||null;render();$('#rule-form input[name=name]')?.focus();return}
  if(el.dataset.toggleRule){const x=(S.config?.rules||[]).find(x=>x.id===el.dataset.toggleRule);if(!x)return;await api('/api/v1/rules/'+encodeURIComponent(x.id),{method:'PUT',json:{...x,enabled:!x.enabled}});await refresh();alertUser('Rule state updated');return}
  if(id==='cancel-rule-edit'){S.editRule=null;render();return}
  if(id==='preview-quarantine'){if(!S.inspect)return;S.preview=await api('/api/v1/messages/'+encodeURIComponent(S.inspect.id)+'/preview');render();$('#preview-text')?.focus();return}

  if(id==='signout'){await api('/api/v1/logout',{method:'POST'});S.authenticated=false;S.me=null;S.onceToken=null;render();return}
  if(el.dataset.inspect){S.lastInspectedId=el.dataset.inspect;S.preview=null;S.inspect=S.messages.find(m=>m.id===el.dataset.inspect)||await api('/api/v1/messages/'+encodeURIComponent(el.dataset.inspect));render();$('#close-detail')?.focus();return}
  if(id==='close-detail'||id==='detail-layer'){S.preview=null;S.inspect=null;render();restoreInspectionFocus();return}
  if(id==='copy-token'){await navigator.clipboard.writeText(S.onceToken);alertUser('Key copied');return}
  if(el.dataset.neuralLabel){const label=el.dataset.neuralLabel;if(!S.inspect || !confirm(`Train the neural model with this confirmed ${label} message? This modifies future scoring.`))return;await api('/api/v1/neural/train/'+encodeURIComponent(S.inspect.id)+'?label='+label,{method:'POST'});await refresh();alertUser('Neural classifier trained');return}
  if(el.dataset.fuzzyDelete){if(!confirm('Delete this fuzzy fingerprint? Future scans will no longer match it.'))return;await api('/api/v1/fuzzy/entries/'+encodeURIComponent(el.dataset.fuzzyDelete),{method:'DELETE'});await refresh();alertUser('Fingerprint deleted');return}
  if(id==='discard-quarantine'){if(!confirm('Permanently delete this quarantined email? The original cannot be recovered or released afterward.'))return;const discarded=await api('/api/v1/messages/'+S.inspect.id+'/quarantine',{method:'DELETE'});await refresh();S.inspect=discarded;render();alertUser('Quarantined original permanently deleted');return}
  if(id==='release'){if(!confirm('Release this original quarantined message to its recipient(s)? This cannot be undone.'))return;const updated=await api('/api/v1/messages/'+S.inspect.id+'/release',{method:'POST'});await refresh();S.inspect=updated;render();alertUser('Message released to the SMTP relay');return}
  const deletion=[['delete-rule','rules'],['delete-dns','dns-lists'],['delete-user','users'],['delete-token','tokens']].find(([attr])=>el.dataset[attr]!==undefined);
  if(deletion){const [attr,path]=deletion;const target=el.dataset[attr];if(!confirm(`Remove ${target}? This action cannot be undone.`))return;await api('/api/v1/'+path+'/'+encodeURIComponent(target),{method:'DELETE'});await refresh();alertUser('Removed successfully')}
}catch(e){alertUser(e.message,true)}});
document.addEventListener('change',event=>{if(event.target.id==='action-filter'){S.filterAction=event.target.value;S.historyResults=null;render()}});
document.addEventListener('input',event=>{if(event.target.id==='search'){const pos=event.target.selectionStart;S.search=event.target.value;S.historyResults=null;render();const el=$('#search');if(el){el.focus();el.setSelectionRange(pos,pos)}}});
function restoreInspectionFocus(){const target=[...document.querySelectorAll('[data-inspect]')].find(el=>el.dataset.inspect===S.lastInspectedId);target?.focus()}
document.addEventListener('keydown',event=>{
  if(!S.inspect)return;
  if(event.key==='Escape'){S.inspect=null;render();restoreInspectionFocus();return}
  if(event.key!=='Tab')return;
  const dialog=document.querySelector('.detail-panel');
  if(!dialog)return;
  const els=[...dialog.querySelectorAll('a[href],button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled),[tabindex="0"]')].filter(el=>el.getClientRects().length);
  if(!els.length)return;
  const first=els[0],last=els[els.length-1];
  if(event.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){event.preventDefault();last.focus()}
  else if(!event.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){event.preventDefault();first.focus()}
});
document.addEventListener('submit',async event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const id=form.id;const submit=form.querySelector('[type="submit"],button:not([type])');if(submit)submit.disabled=true;
  try{const fields=Object.fromEntries(new FormData(form).entries());let data;
    if(form.classList.contains('signal-form')){
      const symbol=form.dataset.symbol;
      data={score:Number(fields.score),enabled:fields.enabled==='on'};
      await api('/api/v1/signals/'+encodeURIComponent(symbol),{method:'PUT',json:data});
      await refresh();alertUser('Built-in scoring signal updated');return;
    }
    switch(id){
    case 'setup-form':await api('/api/v1/setup',{method:'POST',json:fields});S.setup=false;S.me=await api('/api/v1/me');S.authenticated=true;S.section=permitted(sectionFromLocation())?sectionFromLocation():'overview';await refresh();alertUser('SpamGate setup completed');break;
    case 'login-form':await api('/api/v1/login',{method:'POST',json:fields});S.me=await api('/api/v1/me');S.authenticated=true;S.section=permitted(sectionFromLocation())?sectionFromLocation():'overview';await refresh();break;
    case 'scan-form':{
      const file=fields.eml;if(!file||file.size>10485760)throw Error('Select an .eml file smaller than 10 MiB');
      const headers={'Content-Type':'message/rfc822','X-SpamGate-Sender':String(fields.sender||''),'X-SpamGate-Recipients':String(fields.recipients||''),'X-SpamGate-Client-IP':String(fields.client_ip||'' )};data=await api('/api/v1/scan',{method:'POST',headers,body:await file.arrayBuffer()});await refresh();S.inspect=data;render();alertUser('Message scanned and recorded');break}
    case 'fuzzy-form':{
      const file=form.elements.eml.files[0];if(!file||file.size>10*1024*1024)throw Error('Choose a .eml file under 10 MiB');
      await api('/api/v1/fuzzy/train?label='+encodeURIComponent(fields.label),{method:'POST',headers:{'Content-Type':'message/rfc822'},body:await file.arrayBuffer()});await refresh();alertUser('Near-duplicate reference fingerprint trained');break}
    case 'bayes-form':{
      const file=fields.eml;if(!file||file.size>10485760)throw Error('Select an .eml file smaller than 10 MiB');
      await api('/api/v1/bayes/train?label='+encodeURIComponent(fields.label),{method:'POST',headers:{'Content-Type':'message/rfc822'},body:await file.arrayBuffer()});await refresh();alertUser('Classifier trained with confirmed '+fields.label+' sample');break}
    case 'rule-form':data={name:fields.name,kind:fields.kind,value:fields.value,score:Number(fields.score||0),action:fields.action,priority:Number(fields.priority||0),expires_at:fields.expires_at?new Date(fields.expires_at).toISOString():undefined,enabled:S.editRule?S.editRule.enabled:true};if(S.editRule){await api('/api/v1/rules/'+encodeURIComponent(S.editRule.id),{method:'PUT',json:data});S.editRule=null}else await api('/api/v1/rules',{method:'POST',json:data});await refresh();alertUser('Rule saved');break;
    case 'dns-form':data={zone:fields.zone,score:Number(fields.score),enabled:fields.enabled==='on'};await api('/api/v1/dns-lists',{method:'POST',json:data});await refresh();alertUser('DNS blocklist added');break;
    case 'user-form':await api('/api/v1/users',{method:'POST',json:fields});await refresh();alertUser('Mailbox account created');break;
    case 'token-form':data=await api('/api/v1/tokens',{method:'POST',json:fields});S.onceToken=data.token;await refresh();alertUser('API key generated');break;
    case 'settings-form':data={site_name:fields.site_name,tag_threshold:Number(fields.tag_threshold),quarantine_threshold:Number(fields.quarantine_threshold),reject_threshold:Number(fields.reject_threshold),retention_days:Number(fields.retention_days),max_history:Number(fields.max_history),dnsbl_enabled:fields.dnsbl_enabled==='on'};await api('/api/v1/settings',{method:'PUT',json:data});await refresh();alertUser('Policy saved');break;
    case 'override-form':data={action:fields.action,reason:fields.reason};const changed=await api('/api/v1/messages/'+S.inspect.id+'/override',{method:'POST',json:data});await refresh();S.inspect=changed;render();alertUser('Decision reclassified and audited');break;
    }
  }catch(e){alertUser(e.message,true)}finally{if(submit)submit.disabled=false}
});
start();setInterval(()=>{if(S.authenticated&&!S.inspect&&document.visibilityState==='visible'&&['overview','history'].includes(S.section))refresh()},30000);
